solution:
use xiom.io;

enum Direction {
  North,
  South,
  East,
  West,
}

fn go(dir: Direction) -> Str {
  return match dir {
    North => "Snowy mountains ahead",
    South => "Sunny beach ahead",
    East => "Dense forest ahead",
    West => "Vast desert ahead",
  };
}

fn main() -> Int {
  io.println(go(Direction.North).to_str());
  io.println(go(Direction.East).to_str());
  return 0;
}
